def _cut(s, n):
    return s if len(s) <= n else s[:n].rsplit(" ", 1)[0] + " …"


def _last(s):
    lines = [x for x in (s or "").splitlines() if x.strip()]
    return _cut(lines[-1].strip(), 140) if lines else ""


HEAD = ("Solve the following code problem step by step. The last part of your response should be the solution to the problem "
        "in form ```\npython\nCODE\n``` where CODE is the solution for the problem.\n\n")
FOOT = "\nRemember to put your solution inside the ```\npython\nCODE\n``` tags"


def _build(runs):  # PROBLEMS from the regrade rows
    rows = {c: [json.loads(x) for x in open(os.path.join(runs, DATA["rows"].format(cell=c)))] for c in CELLS}
    uids = [r["uid"] for r in rows[CELLS[0]]]
    assert len(uids) == DATA["n"] == len(set(uids)) and all([r["uid"] for r in rows[c]] == uids for c in CELLS)
    out = []
    for k, uid in enumerate(uids):
        pr = rows[CELLS[0]][k]["prompt"]
        assert pr.startswith(HEAD) and pr.endswith(FOOT) and all(rows[c][k]["prompt"] == pr for c in CELLS), uid
        cells = []
        for c in CELLS:
            r = rows[c][k]
            assert r["sampling"]["temperature"] == 1.0 and r["sampling"]["top_p"] == 1.0 and r["seed"] == DATA["seed"] + r["idx"], (c, uid)
            changed = "code_v3" in r
            first = "p" if r["passed"] else "u" if changed else "f"
            why = ("o" if r["mode_v3"] == "unopened" else "c") if changed else ""
            end = r["text"][-(DATA["end_changed"] if changed else DATA["end"]):]
            cells.append([first + ("p" if r["passed_v3"] else "f") + why, r["n_new"], int(r["cap_hit"]),
                          "" if r["passed"] else _last(r["stderr_tail"]),
                          _last(r["stderr_tail_v3"]) if changed and not r["passed_v3"] else "", end])
        out.append([uid, _cut(pr[len(HEAD):-len(FOOT)], DATA["task"])] + cells)
    return out, rows


PAGE = r"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Invariant: __TITLE__</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@62..125,100..900&display=swap">
<style>
/* The tokens and the light of tools/architecture.py: one lit plate, glass in a dark room, porcelain on a grey table
   with a cast shadow in place of the glow. The light comes from the upper left in both. A program that passed is a lit
   blue dot, a failed one a faint dot, and a program the first rule did not read as written is marked as a problem (red). */
:root {
  color-scheme: light dark;
  --paper: #eceef0; --sheet: #fbfcfc; --ink: #101820; --mute: #56636d; --faint: #606c76; --rule: #d3d9de;
  --blue: #1f43d6; --red: #c41e34;
  --glass-hi: #ffffff; --glass: #f9fafb; --glass-lo: #dfe4e8;
  --rim-a: rgba(16, 24, 32, .28); --rim-b: rgba(16, 24, 32, .58); --rim-c: rgba(16, 24, 32, .9);
  --glow: 0; --shadow: 1; --spec: 0; --bloom: .4;
  --dot-off: .2; --red-on: .9;
}
@media (prefers-color-scheme: dark) {
  :root {
    --paper: #080c11; --sheet: #111922; --ink: #e9eff3; --mute: #93a1ad; --faint: #788590; --rule: #1c2630;
    --blue: #8fb1ff; --red: #ff6b7c;
    --glass-hi: #34485e; --glass: #152029; --glass-lo: #090e14;
    --rim-a: rgba(255, 255, 255, .92); --rim-b: rgba(255, 255, 255, .1); --rim-c: rgba(143, 177, 255, .45);
    --glow: 1; --shadow: 0; --spec: 1; --bloom: 1;
    --dot-off: .24; --red-on: .95;
  }
}
* { box-sizing: border-box; }
html { background: var(--paper); }
body {
  margin: 0; color: var(--ink); background: var(--paper);
  font: 400 15px/1.5 "Archivo", ui-sans-serif, -apple-system, "Segoe UI", system-ui, sans-serif;
  font-variant-numeric: tabular-nums; -webkit-font-smoothing: antialiased;
}
button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: left; }
a { color: inherit; }
:focus-visible { outline: 2px solid var(--blue); outline-offset: 3px; border-radius: 3px; }
.page {
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(320px, 27vw); grid-template-rows: auto minmax(0, 1fr);
  gap: 0; height: 100vh; min-height: 620px; max-width: 1840px; margin: 0 auto; padding: 20px 40px 28px;
}
.top { grid-column: 1 / -1; display: flex; align-items: center; gap: 26px; font-size: 13px; padding-bottom: 16px; border-bottom: 1px solid var(--rule); }
.name { font-weight: 740; font-stretch: 122%; font-size: 15px; letter-spacing: .02em; margin: 0 6px 0 0; }
.top a { color: var(--mute); text-decoration: none; white-space: nowrap; transition: color .15s ease; }
.top a:hover { color: var(--ink); }
.top a[aria-current] { color: var(--ink); font-weight: 600; }

/* The picture: one plate with three rows of 538 marks and the counts, and the one switch under it */
.stage { min-height: 0; min-width: 0; display: flex; flex-direction: column; justify-content: center; padding: 8px 40px 0 0; }
svg { width: 100%; max-height: calc(100vh - 236px); display: block; overflow: visible; touch-action: pan-y; cursor: default; user-select: none; -webkit-user-select: none; }
svg:focus:not(:focus-visible) { outline: none; }
svg text { font-family: inherit; fill: var(--ink); font-stretch: 106%; }
svg * { pointer-events: none; }
.atmo { opacity: var(--glow); }
.shade { fill: var(--ink); opacity: calc(var(--shadow) * .17); }
.spec { opacity: var(--spec); }
.back { fill: var(--glass-lo); stroke: var(--rim-b); stroke-width: 1; }
.plate { fill: url(#body) var(--sheet); stroke: url(#rim) var(--ink); stroke-width: 1.7; }
.mk { fill: none; stroke-linecap: round; }
.mk.p { stroke: var(--blue); }
.mk.f { stroke: var(--ink); opacity: var(--dot-off); }
.mk.u { stroke: var(--red); opacity: var(--red-on); }
.mk.halo { stroke: var(--blue); opacity: calc(var(--bloom) * .09); }
.sel { fill: none; stroke: var(--ink); stroke-width: 1.5; }
.cap { fill: var(--mute) !important; font-weight: 500; }
.band { font-weight: 640; }
.band.sft { font-weight: 720; }
.bsub { fill: var(--mute) !important; font-weight: 480; }
.cnt { font-weight: 680; }
.of { fill: var(--mute) !important; font-weight: 480; }
.big { font-weight: 660; letter-spacing: -.035em; font-stretch: 100%; fill: var(--blue) !important; }
.lab { font-weight: 600; }
.sub { fill: var(--mute) !important; font-weight: 480; }
.dif { font-weight: 620; }
.dif.lit { fill: var(--blue) !important; }
.kl { fill: var(--mute) !important; font-weight: 500; }
.kd.p { fill: var(--blue); } .kd.f { fill: var(--ink); opacity: var(--dot-off); } .kd.u { fill: var(--red); opacity: var(--red-on); }
.control { align-self: center; display: flex; flex-direction: column; align-items: center; margin-top: 14px; }
.clab { font-size: 13px; color: var(--mute); font-weight: 560; }
.switch { display: inline-flex; margin-top: 6px; border: 1px solid var(--faint); border-radius: 999px; padding: 3px; }
.switch button { padding: 8px 18px; border-radius: 999px; font-weight: 600; font-size: 15px; white-space: nowrap; transition: background .15s ease, color .15s ease; }
.switch button:hover { color: var(--blue); }
.switch button[aria-pressed="true"] { background: var(--ink); color: var(--paper); }
.switch button[aria-pressed="true"]:hover { color: var(--paper); }
.hint { margin: 10px 0 0; font-size: 13px; color: var(--mute); text-align: center; max-width: 78ch; min-height: 2.9em; }

/* One drawn entrance, then only the slow sway and what the reader changes */
@keyframes draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes fade { from { opacity: 0; } }
.enter .draw { stroke-dasharray: 1; animation: draw 1.1s cubic-bezier(.6, 0, .2, 1) both; }
.enter .atmo, .enter .shade, .enter .spec, .enter .back { animation: fade 1.3s .15s both; }
.enter .marks { animation: fade .9s .45s both; }
.enter .words { animation: fade .7s .7s both; }

/* The words */
.side {
  min-width: 0; min-height: 0; overflow-y: auto; scrollbar-width: none;
  padding: clamp(20px, 7vh, 96px) 0 0 40px; border-left: 1px solid var(--rule);
}
.problem { margin: 0; color: var(--mute); font-size: clamp(16px, 1.25vw, 20px); line-height: 1.3; max-width: 26ch; }
.say { margin: 14px 0 0; font-size: clamp(25px, 2.15vw, 40px); line-height: 1.14; font-weight: 300; font-stretch: 102%; letter-spacing: -.016em; max-width: 17ch; }
.say b { font-weight: 620; white-space: nowrap; }
.pane { margin-top: clamp(22px, 4vh, 44px); }
.more { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--rule); }
.more button { display: flex; width: 100%; justify-content: space-between; align-items: baseline; padding: 12px 0; border-bottom: 1px solid var(--rule); font-size: 17px; font-weight: 520; transition: color .15s ease; }
.more button span { color: var(--faint); font-size: 20px; line-height: 1; }
.more button:hover { color: var(--blue); }
.dhead { display: flex; align-items: baseline; justify-content: space-between; gap: 16px; padding: 0 6px 12px 0; border-bottom: 1px solid var(--ink); }
.dhead h2 { margin: 0; font-size: 17px; font-weight: 660; font-stretch: 114%; letter-spacing: .008em; }
.close { font-size: 13px; color: var(--mute); }
.close:hover { color: var(--ink); }
.lead { margin: 18px 0 0; font-size: clamp(17px, 1.3vw, 21px); line-height: 1.36; font-weight: 380; max-width: 30ch; overflow-wrap: anywhere; }
.lead.q { font-size: 14.5px; line-height: 1.45; color: var(--mute); max-width: 48ch; white-space: pre-wrap; tab-size: 4; }
.facts { list-style: none; margin: 18px 0 0; padding: 0; font-size: 14.5px; color: var(--mute); max-width: 40ch; overflow-wrap: anywhere; }
.facts li { padding: 8px 0; border-top: 1px solid var(--rule); }
.facts a { color: var(--ink); text-decoration: none; border-bottom: 1px solid var(--faint); }
.facts a:hover { color: var(--blue); }
.sub2 { margin: 20px 0 0; font-size: 13.5px; color: var(--mute); }
.sub2 b { color: var(--ink); font-weight: 650; }
.answers { list-style: none; margin: 6px 0 0; padding: 0; font-size: 14px; color: var(--mute); max-width: 46ch; }
.answers li { padding: 6px 0 6px 12px; border-top: 1px solid var(--rule); border-left: 2px solid transparent; overflow-wrap: anywhere; }
.answers li.on { border-left-color: var(--blue); }
.answers .who { color: var(--ink); font-weight: 640; }
.answers .p { color: var(--blue); font-weight: 650; } .answers .f { color: var(--ink); font-weight: 600; } .answers .u { color: var(--red); font-weight: 650; }
.answers .g { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin: 0 8px 1px 0; vertical-align: middle; }
.answers .g.p { background: var(--blue); } .answers .g.f { background: var(--faint); opacity: .55; } .answers .g.u { background: var(--red); }
.answers .err { display: block; font-size: 12.5px; color: var(--faint); margin-top: 2px; }
.tcap { margin: 10px 0 0; font-size: 12.5px; color: var(--faint); }
.end { margin: 4px 0 0; padding: 6px 0 2px 12px; border-left: 2px solid var(--rule); font: 400 12.5px/1.5 "Archivo", ui-sans-serif, sans-serif;
  font-stretch: 94%; color: var(--mute); max-width: 52ch; white-space: pre-wrap; overflow-wrap: anywhere; tab-size: 4; max-height: 22em; overflow-y: auto; position: relative; }
.end mark { background: none; color: var(--red); font-weight: 700; }
.end .flag { display: block; color: var(--red); font-weight: 600; font-stretch: 100%; }
.note { margin: 10px 0 0; font-size: 13px; color: var(--mute); max-width: 46ch; }
.steps { display: flex; justify-content: space-between; margin-top: 16px; font-size: 13px; color: var(--mute); }
.steps button:hover { color: var(--ink); }
@media (max-width: 900px) {
  /* On a phone the order is: the problem, the finding, the picture, the depth. */
  .page { display: flex; flex-direction: column; height: auto; min-height: 0; padding: 16px 16px 40px; }
  .top { gap: 13px; padding-bottom: 12px; flex-wrap: wrap; }
  .name { font-stretch: 112%; margin-right: 0; }
  .side { display: contents; }
  .problem { order: 1; margin-top: 20px; max-width: none; }
  .say { order: 2; max-width: 22ch; }
  .stage { order: 3; margin-top: 22px; padding: 0; display: block; }
  .pane { order: 4; margin-top: 22px; }
  svg { max-height: none; }
  .control { width: 100%; }
  .switch { display: grid; grid-template-columns: 1fr 1fr; gap: 2px; border-radius: 22px; width: 100%; }
  .switch button { text-align: center; padding: 10px 6px; font-size: 14px; white-space: normal; line-height: 1.2; }
}
@media (prefers-reduced-motion: reduce) {
  .enter * { animation: none !important; }
  .switch button, .more button, .top a { transition: none; }
}
</style>
</head>
<body>
<div class="page">
  <header class="top">
    <h1 class="name">Invariant</h1>
    <a href="/">Board</a>
    <a href="/architecture">Design</a>
    <a href="/proof">Proof</a>
    <a href="/findings" aria-current="page">Findings</a>
  </header>
  <div class="stage" id="stage">
    <svg id="svg" role="img" tabindex="0"></svg>
    <div class="control">
      <span class="clab" id="clab">How the grader reads the answer</span>
      <div class="switch" id="switch" role="group" aria-labelledby="clab">
        <button data-rule="0" aria-pressed="false">First rule: fenced block only</button>
        <button data-rule="1" aria-pressed="false">Also an unopened block</button>
      </div>
      <p class="hint" id="hint"></p>
    </div>
  </div>
  <div class="side">
    <p class="problem" id="problem"></p>
    <p class="say" id="say"></p>
    <div class="pane" id="pane" aria-live="polite"></div>
  </div>
</div>
<script>
const C = __CONFIG__, D = C.data, $ = id => document.getElementById(id);
const still = matchMedia("(prefers-reduced-motion: reduce)"), narrow = matchMedia("(max-width: 900px)");
const esc = s => String(s ?? "").replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
const RAD = Math.PI / 180, f = n => n.toFixed(1), mix = (a, b, q) => a + (b - a) * q;
const ease = p => p < .5 ? 2 * p * p : 1 - (-2 * p + 2) ** 2 / 2, clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const num1 = v => (Math.abs(v) < .05 ? "0.0" : (v < 0 ? "−" : "") + Math.abs(v).toFixed(1)), sgn = v => (v < 0 ? "−" : "+") + Math.abs(v).toFixed(1);
const fmt = n => Math.round(n).toLocaleString("en-US");

/* The three rows, top to bottom, and the two rules. A problem's state in a row is a string: first rule p (passed), f
   (failed) or u (failed, and the second rule reads a different program); second rule p or f; then o (no opening fence)
   or c (a CODE line removed) when the second rule reads a different program. */
const N = D.n;
const M = [{ name: "Base + cue", sub: "the base model, no training" },
           { name: "Think-SFT + cue", sub: "trained on worked solutions, no reward" },
           { name: "RL", sub: "trained with a reward on code" }];
const RULES = [{ key: "first", label: "First rule",
                 hint: "The first rule runs the last fenced python block of an answer. An answer whose program has no opening code fence is run whole as Python, and fails." },
               { key: "", label: "Second rule",
                 hint: "The second rule also reads a program that follows a line python with no opening code fence, and drops lines that say only CODE, a word copied from the prompt." }];
const PR = C.problems.map(([uid, ...s]) => ({ uid, s, key: uid.replace("/", "-") }));
const at0 = (k, m, r) => PR[k].s[m][r];  // a problem's outcome in row m under rule r: "p", "f" or "u"
/* Each row is sorted by outcome: passed from the left, failed from the right, the unread programs between. Under the
   second rule a mark whose outcome stays keeps its place, and each part's free places are taken by the marks that join
   it, in problem order: so only the marks that change travel. */
function slots(m) {
  const ks = PR.map((_, k) => k), A = [], B = [];
  [...ks.filter(k => at0(k, m, 0) === "p"), ...ks.filter(k => at0(k, m, 0) === "u"), ...ks.filter(k => at0(k, m, 0) === "f")].forEach((k, s) => { A[k] = s; });
  const P = ks.filter(k => at0(k, m, 1) === "p").length;
  const fill = (lo, hi, o) => {
    const used = new Set(), come = [];
    for (const k of ks) if (at0(k, m, 1) === o) {
      if (at0(k, m, 0) === o && A[k] >= lo && A[k] < hi) { B[k] = A[k]; used.add(A[k]); } else come.push(k);
    }
    let s = lo;
    for (const k of come) { while (used.has(s)) s++; B[k] = s++; }
  };
  fill(0, P, "p"); fill(P, N, "f");
  return [A, B];
}
const SL = M.map((_, m) => slots(m));
const COUNT = [0, 1].map(r => M.map((_, m) => PR.filter((_, k) => at0(k, m, r) === "p").length));
let TX = null;  // the texts, in a block at the end of the page, read on the first click
const texts = () => TX || (TX = JSON.parse($("texts").textContent));
const S = { rule: 1, from: 1, t0: -1e9, open: null, selM: 1, g: null, el: {}, shown: {}, last: 0, pos: [[], [], []], touched: false, delay: [[], [], []], total: 0 };

/* Geometry, in a small 3D space around the plate's centre (x right, y down, z toward the viewer). A row's 538 places fill
   x0..x1, column by column from the top left. Beside the rows (on a phone, above them) the large number and the
   comparisons. */
function geo() {
  return narrow.matches
    ? { w: 480, h: 1010, cx: 240, cy: 505, D: 2000, a: [6, 8, 474, 1002], r: 22, deep: 30, blur: 12, phone: true,
        x0: 34, x1: 446, rows: 13, top: [394, 582, 770], fn: 17, fs: 17, fc: 19, nameUp: 12,
        capY: 352, bigX: 30, bigY: 124, fb: 104, labY: [160, 184], difY: [226, 250, 284, 308], key: [[36, 940], [36, 966], [190, 940]] }
    : { w: 1000, h: 600, cx: 500, cy: 300, D: 2200, a: [24, 18, 976, 582], r: 30, deep: 40, blur: 16,
        x0: 66, x1: 606, rows: 10, top: [120, 272, 424], fn: 16, fs: 15, fc: 18, nameUp: 14,
        capY: 62, bigX: 650, bigY: 230, fb: 136, labY: [266, 290], difY: [336, 358, 394, 416], key: [[658, 482], [658, 508], [658, 534]] };
}
const pitch = g => (g.x1 - g.x0) / Math.ceil(N / g.rows);
const place = (g, m, s) => { const p = pitch(g); return [g.x0 + (Math.floor(s / g.rows) + .5) * p, g.top[m] + (s % g.rows + .5) * p]; };
const V = { c1: 1, s1: 0, c2: 1, s2: 0, px: 0, py: 0, tx: 0, ty: 0 };
function aim(yaw, tilt) { V.c1 = Math.cos(yaw * RAD); V.s1 = Math.sin(yaw * RAD); V.c2 = Math.cos(tilt * RAD); V.s2 = Math.sin(tilt * RAD); }
function proj(g, x, y, z) {
  const X = x - g.cx, Y = y - g.cy, x1 = X * V.c1 + z * V.s1, z1 = z * V.c1 - X * V.s1;
  const y1 = Y * V.c2 - z1 * V.s2, k = g.D / (g.D - (z1 * V.c2 + Y * V.s2));
  return [g.cx + x1 * k, g.cy + y1 * k, k];
}
function rounded(g, [x0, y0, x1, y1], r, z) {  // a rounded rectangle at depth z
  const p = [], corner = (cx, cy, a0) => { for (let i = 0; i <= 6; i++) p.push(proj(g, cx + r * Math.cos((a0 + 15 * i) * RAD), cy + r * Math.sin((a0 + 15 * i) * RAD), z)); };
  corner(x1 - r, y0 + r, -90); corner(x1 - r, y1 - r, 0); corner(x0 + r, y1 - r, 90); corner(x0 + r, y0 + r, 180);
  return "M" + p.map(q => f(q[0]) + " " + f(q[1])).join("L") + "Z";
}

const LV = 7, CLS = ["p", "f", "u"], RAD_OF = { p: .4, f: .27, u: .4 };
function build() {
  const g = S.g = geo(), svg = $("svg"), [ax0, ay0, ax1, ay1] = g.a, aw = ax1 - ax0, ah = ay1 - ay0;
  const stop = (o, color, alpha) => `<stop offset="${o}" style="stop-color:${color}${alpha == null ? "" : ";stop-opacity:" + alpha}"/>`;
  const T = (cls, id, fs, extra = "") => `<text class="${cls}" id="${id}" font-size="${fs}" ${extra}></text>`;
  svg.setAttribute("viewBox", `0 0 ${g.w} ${g.h}`);
  svg.innerHTML = "<defs>" +
    `<radialGradient id="body" cx=".3" cy=".22" r=".95">${stop(0, "var(--glass-hi)")}${stop(.46, "var(--glass)")}${stop(1, "var(--glass-lo)")}</radialGradient>` +
    `<linearGradient id="rim" x1=".06" y1=".04" x2=".94" y2=".96">${stop(0, "var(--rim-a)")}${stop(.56, "var(--rim-b)")}${stop(1, "var(--rim-c)")}</linearGradient>` +
    `<radialGradient id="atmo">${stop(.5, "var(--blue)", .2)}${stop(.72, "var(--blue)", .06)}${stop(1, "var(--blue)", 0)}</radialGradient>` +
    `<radialGradient id="spec">${stop(0, "#fff", .2)}${stop(1, "#fff", 0)}</radialGradient>` +
    `<filter id="soft" x="-20%" y="-20%" width="140%" height="150%"><feGaussianBlur stdDeviation="${g.blur}"/></filter></defs>` +
    `<ellipse class="atmo" cx="${g.cx}" cy="${g.cy}" rx="${f(aw * .8)}" ry="${f(ah * .9)}" fill="url(#atmo)"/>` +
    `<rect class="shade" x="${f(ax0 + aw * .012)}" y="${f(ay0 + ah * .04)}" width="${aw}" height="${ah}" rx="${g.r}" filter="url(#soft)"/>` +
    `<path class="back" id="back"/><path class="plate draw" id="plate" pathLength="1"/>` +
    `<ellipse class="spec" cx="${f(ax0 + aw * .3)}" cy="${f(ay0 + ah * .24)}" rx="${f(aw * .3)}" ry="${f(ah * .2)}" transform="rotate(-14 ${f(ax0 + aw * .3)} ${f(ay0 + ah * .24)})" fill="url(#spec)"/>` +
    `<g class="marks"><path class="mk halo" id="halo"/>` + CLS.map(c => [...Array(LV)].map((_, l) => `<path class="mk ${c}" id="${c}${l}"/>`).join("")).join("") +
    `<path class="sel" id="sel"/></g><g class="words">` + T("cap", "cap", g.fs) +
    M.map((m, k) => T("band" + (k === 1 ? " sft" : ""), "bn" + k, g.fn) + (g.phone ? "" : T("bsub", "bs" + k, g.fs - 1)) +
      `<text id="bc${k}" font-size="${g.fs}" text-anchor="end"><tspan class="cnt" id="bv${k}" font-size="${g.fc}"></tspan><tspan class="of" id="bo${k}"></tspan></text>`).join("") +
    T("big", "big", g.fb) + T("lab", "lab0", g.fs + 2) + T("sub", "lab1", g.fs) +
    [0, 1, 2, 3].map(i => T(i % 2 ? "sub" : "dif", "d" + i, g.fs)).join("") +
    CLS.map((c, i) => `<circle class="kd ${c}" id="kd${i}" r="${c === "f" ? 3.2 : 4.4}"/>${T("kl", "kt" + i, g.fs)}`).join("") + "</g>";
  S.el = {}; S.shown = {};
  svg.querySelectorAll("[id]").forEach(e => { S.el[e.id] = e; });
}

/* One frame. A mark whose place or outcome changes between the two rules travels from its place under the earlier rule
   to its place under the new one, lifting toward the viewer on the way, and takes its new colour halfway. The marks of a
   row leave one after another, 3 ms apart, and each takes 620 ms. Every count is the number of marks drawn blue now. */
const DUR = 620, STAG = 3;
function draw(now) {
  const g = S.g, E = S.el, el = now - S.t0, P = pitch(g);
  const text = (id, v) => { if (S.shown[id] !== v) E[id].textContent = S.shown[id] = v; };
  const at = (e, q, dy) => { e.setAttribute("x", f(q[0])); e.setAttribute("y", f(q[1] + (dy || 0))); };
  E.back.setAttribute("d", rounded(g, g.a, g.r, -g.deep));
  E.plate.setAttribute("d", rounded(g, g.a, g.r, 0));
  const paths = {}; CLS.forEach(c => { for (let l = 0; l < LV; l++) paths[c + l] = ""; });
  let halo = "", sel = "";
  const cnt = [0, 0, 0], dmax = P * .4 * 1.25;
  for (let m = 0; m < 3; m++) {
    const A = SL[m][S.from === 0 ? 0 : 1], B = SL[m][S.rule === 0 ? 0 : 1];
    for (let k = 0; k < N; k++) {
      const ca = at0(k, m, S.from), cb = at0(k, m, S.rule), moves = A[k] !== B[k] || ca !== cb;
      const q = moves ? clamp((el - S.delay[m][k]) / DUR, 0, 1) : 1, e = ease(q);
      const pa = place(g, m, A[k]), pb = place(g, m, B[k]), c = q < .5 ? ca : cb;
      const p = proj(g, mix(pa[0], pb[0], e), mix(pa[1], pb[1], e), 6 + (moves ? 30 * Math.sin(Math.PI * q) : 0));
      if (c === "p") cnt[m]++;
      const d = 2 * RAD_OF[c] * P * p[2], l = clamp(Math.round((d / dmax) * (LV - 1)), 0, LV - 1), seg = `M${f(p[0])} ${f(p[1])}h0`;
      paths[c + l] += seg;
      if (c === "p") halo += seg;
      S.pos[m][k] = p;
      if (S.open === PR[k].key) { const rr = P * .82 * p[2]; sel += `M${f(p[0] - rr)} ${f(p[1])}a${f(rr)} ${f(rr)} 0 1 0 ${f(2 * rr)} 0a${f(rr)} ${f(rr)} 0 1 0 ${f(-2 * rr)} 0`; }
    }
  }
  for (const id in paths) if (S.shown[id] !== paths[id]) {
    const l = +id.slice(1);
    E[id].setAttribute("d", paths[id]); E[id].setAttribute("stroke-width", f(dmax * (l + .5) / LV)); S.shown[id] = paths[id];
  }
  E.halo.setAttribute("d", halo); E.halo.setAttribute("stroke-width", f(P * .95));
  E.sel.setAttribute("d", sel);

  // The words: each row's name and count, the large number and the two comparisons, from the marks as drawn. The
  // intervals belong to one rule: they leave when the marks start and return when the marks have settled.
  const done = el >= S.total, shown = done || el > S.total / 2 ? S.rule : S.from;
  text("cap", g.phone ? `${N} code problems, one mark each` : `${N} code problems, one mark per problem and row. One sample per model, T 1.0.`);
  at(E.cap, proj(g, g.x0, g.capY, 10));
  M.forEach((m, k) => {
    text("bn" + k, m.name); at(E["bn" + k], proj(g, g.x0, g.top[k] - g.nameUp, 10));
    if (!g.phone) { text("bs" + k, m.sub); at(E["bs" + k], proj(g, g.x0 + (E["bn" + k].getComputedTextLength() || 90) + 10, g.top[k] - g.nameUp, 10)); }
    text("bv" + k, String(cnt[k])); text("bo" + k, ` of ${N} passed`);
    at(E["bc" + k], proj(g, g.x1, g.top[k] - g.nameUp, 10));
  });
  text("big", String(cnt[1]));
  at(E.big, proj(g, g.bigX, g.bigY, 14));
  text("lab0", `of ${N} passed, Think-SFT + cue`); at(E.lab0, proj(g, g.bigX + 4, g.labY[0], 14));
  text("lab1", `${RULES[shown].label}, T 1.0, one sample, no reward`); at(E.lab1, proj(g, g.bigX + 4, g.labY[1], 14));
  const ds = D.diff[shown === 0 ? "v1" : "v3"], iv = d => `95 % interval ${num1(d[1])} to ${num1(d[2])}` + (d[1] <= 0 && d[2] >= 0 ? (Math.abs(d[2]) < .05 || Math.abs(d[1]) < .05 ? ", reaches 0" : ", includes 0") : "");
  const pts = j => 100 * (cnt[1] - cnt[j]) / N;
  text("d0", `${sgn(pts(0))} points against Base + cue (${cnt[0]})`);
  text("d1", done ? iv(ds.base_cue) : "");
  text("d2", `${sgn(pts(2))} points against RL (${cnt[2]})`);
  text("d3", done ? iv(ds.rl_plain) : "");
  E.d0.setAttribute("class", pts(0) > 0 ? "dif lit" : "dif");
  [0, 1, 2, 3].forEach(i => at(E["d" + i], proj(g, g.bigX + 4, g.difY[i], 14)));
  const keys = ["passed the tests", "failed", shown === 0 ? (g.phone ? "program not read" : "program written, not read by the first rule") : (g.phone ? "not read: none now" : "program not read: none under the second rule")];
  keys.forEach((label, i) => {
    const q = proj(g, g.key[i][0], g.key[i][1], 8);
    E["kd" + i].setAttribute("cx", f(q[0])); E["kd" + i].setAttribute("cy", f(q[1]));
    text("kt" + i, label); at(E["kt" + i], [q[0] + 11, q[1]], g.fs * .35);
  });
}

/* Always on: the plate sways by a few degrees and leans toward the mouse. About 30 frames a second. With reduced
   motion the page shows one still frame per state. */
function frame(now) {
  requestAnimationFrame(frame);
  if (still.matches || now - S.last < 30) return;
  S.last = now;
  const t = now / 1000;
  V.px += (V.tx - V.px) * .1; V.py += (V.ty - V.py) * .1;
  aim(4 * Math.sin(t * .13) + 3.5 * V.px, 2 * Math.sin(t * .09) - 2 * V.py);
  draw(now);
}
function setRule(r, instant) {
  const now = performance.now(), quick = instant || still.matches;
  S.from = quick ? r : S.rule; S.rule = r; S.t0 = quick ? -1e9 : now;
  S.total = 0;
  for (let m = 0; m < 3; m++) {  // the marks that change leave in the order of their new places
    const A = SL[m][S.from], B = SL[m][S.rule];
    const movers = PR.map((_, k) => k).filter(k => A[k] !== B[k] || at0(k, m, S.from) !== at0(k, m, S.rule)).sort((x, y) => B[x] - B[y]);
    S.delay[m] = []; movers.forEach((k, i) => { S.delay[m][k] = i * STAG; });
    S.total = Math.max(S.total, movers.length * STAG + DUR);
  }
  $("switch").querySelectorAll("button").forEach(b => b.setAttribute("aria-pressed", Number(b.dataset.rule) === r));
  $("hint").textContent = RULES[r].hint + " Click a mark to read the problem and the answers.";
  $("svg").setAttribute("aria-label", `538 code problems, one mark per problem in each of three rows, ${RULES[r].label.toLowerCase()}: ` +
    M.map((m, k) => `${m.name} ${COUNT[r][k]} of ${N} passed`).join(", ") + ". Enter opens a problem whose Think-SFT program the first rule did not read.");
  if (still.matches) { aim(0, 0); draw(now); }
}

/* The side column: the five panels, or one problem with the three answers, the row clicked first. */
const SAY = {
  p: () => `<span class="p">passed</span> the tests`,
  f: e => `<span class="f">failed</span>` + (e ? `<span class="err">${esc(e)}</span>` : ""),
  u: (e, why) => `<span class="u">not read as written</span>: ` + (why === "o" ? "the program has no opening code fence, so the whole answer ran as Python" : "the block holds the line CODE copied from the prompt") +
    (e ? `<span class="err">${esc(e)}</span>` : ""),
};
function marked(end, why) {  // the end of an answer, with the line that should follow an opening ``` and the CODE lines marked
  let h = esc(end);
  if (why === "o") {
    const all = [...h.matchAll(/(^|\n)([ \t]*(?:python|py|Python)[ \t]*)(?=\n)/g)], o = all[all.length - 1];
    if (o) { const i = o.index + o[1].length; h = h.slice(0, i) + `<span class="flag">↓ no opening code fence before this line</span><mark>${o[2]}</mark>` + h.slice(i + o[2].length); }
  }
  if (why) h = h.replace(/(^|\n)([ \t]*CODE[ \t]*)(?=\n|$)/g, "$1<mark>$2</mark>");
  return h;
}
function answerBlock(k, m) {
  const p = PR[k], s = p.s[m], [n, cap, e1, e3, end] = texts().rows[k][m], why = s[2] || "";
  const odd = (C.prefix[m] || []).includes(p.uid);
  return `<p class="sub2"><b>${M[m].name}</b>${m === 2 ? ", plain prompt" : ", Code cue"}, T 1.0: ${fmt(n)} tokens generated${cap ? `, cut off at ${fmt(D.cap)}` : ""}.</p>` +
    `<ul class="answers"><li class="${S.rule === 0 ? "on" : ""}"><i class="g ${s[0]}"></i><span class="who">First rule</span>: ${SAY[s[0]](e1, why)}</li>` +
    `<li class="${S.rule === 1 ? "on" : ""}"><i class="g ${s[1]}"></i><span class="who">Second rule</span>: ${SAY[s[1]](why ? e3 : e1)}` +
    (why && !odd ? `<span class="err">${why === "o" ? "read from the line python to the closing fence" : "read without the CODE line"}</span>` : "") + `</li></ul>` +
    (odd ? `<p class="note">Here the second rule's code also cut the word CODE from the start of a longer line, which is not what the rule says; read by its words, this program keeps its first-rule outcome.</p>` : "") +
    `<p class="tcap">The end of the answer (its last ${fmt(end.length)} characters)</p><pre class="end">…${marked(end, why)}</pre>`;
}
function problemPane(k) {
  const p = PR[k], [set, no] = p.uid.split("/");
  return `<div class="dhead"><h2>${set === "HumanEval" ? "HumanEval+" : "MBPP+"}, problem ${esc(no)}</h2><button class="close" data-open="">Close</button></div>` +
    `<p class="lead q">${esc(texts().tasks[k].replace(/\n{3,}/g, "\n\n"))}</p>` +
    `<p class="note">The prompt asks for the program between two code fences (three backticks), as a line python, then CODE, which stands for the program.</p>` +
    [S.selM, ...[0, 1, 2].filter(m => m !== S.selM)].map(m => answerBlock(k, m)).join("") +
    `<div class="steps"><button data-step="-1">‹ Previous problem</button><button data-step="1">Next problem ›</button></div>`;
}
const link = h => h.replace("Imitation beats RL", `<a href="/finding/imitation-beats-rl">Imitation beats RL</a>`);
function pane() {
  const p = C.panels.find(p => p[0] === S.open), k = PR.findIndex(q => q.key === S.open);
  if (k >= 0 && !$("texts")) { addEventListener("DOMContentLoaded", pane, { once: true }); return; }  // opened from the address
  $("pane").innerHTML = k >= 0 ? problemPane(k) : p
    ? `<div class="dhead"><h2>${esc(p[1])}</h2><button class="close" data-open="">Close</button></div><p class="lead">${esc(p[2])}</p>` +
      `<ul class="facts">${p[3].map(x => `<li>${link(esc(x))}</li>`).join("")}</ul>`
    : `<ul class="more">${C.panels.map(p => `<li><button data-open="${p[0]}">${esc(p[1])}<span aria-hidden="true">›</span></button></li>`).join("")}</ul>`;
  // each answer block opens at the line where the opening fence is missing, else at its end
  $("pane").querySelectorAll(".end").forEach(e => { const fl = e.querySelector(".flag"); e.scrollTop = fl ? fl.offsetTop - 6 : e.scrollHeight; });
}

/* The rule and what is open are one value in the address: #[first/][<panel> or <problem>]. The second rule is the default. */
function address(push) {
  const parts = [RULES[S.rule].key, S.open || ""].filter(Boolean);
  const url = parts.length ? "#" + parts.join("/") : location.pathname;
  push ? history.pushState(null, "", url) : history.replaceState(null, "", url);
}
function fromHash(first) {
  const parts = decodeURIComponent(location.hash.slice(1)).split("/"), r = parts.includes("first") ? 0 : 1;
  S.open = parts.find(x => C.panels.some(p => p[0] === x) || PR.some(p => p.key === x)) || null;
  if (first === true) {
    if (!location.hash && !still.matches) {
      // With an empty address the page opens on the first rule and plays the change to the second once by itself.
      setRule(0, true);
      setTimeout(() => { if (!S.touched) setRule(1); }, 1500);
    } else setRule(r, true);
  } else if (r !== S.rule) setRule(r);
  pane();
}
const show = () => $("pane").scrollIntoView({ behavior: still.matches ? "auto" : "smooth", block: narrow.matches ? "start" : "nearest" });
function open(key) {
  const was = S.open;
  S.open = key || null;
  address(true);
  pane();
  if (still.matches) draw(performance.now());
  const to = $("pane").querySelector(key ? ".close" : `[data-open="${was}"]`);
  if (to) to.focus({ preventScroll: true });
  else if (!key) $("svg").focus({ preventScroll: true });
}

/* Click a mark in any row to open its problem, that row's answer first. */
const svg = $("svg");
function svgPoint(e) { const m = svg.getScreenCTM().inverse(); return [m.a * e.clientX + m.c * e.clientY + m.e, m.b * e.clientX + m.d * e.clientY + m.f]; }
function nearest([x, y]) {
  let best = null, bd = (pitch(S.g) * (S.g.phone ? 1.1 : .9)) ** 2;
  S.pos.forEach((row, m) => row.forEach((q, k) => { const d = (q[0] - x) ** 2 + (q[1] - y) ** 2; if (d < bd) { bd = d; best = [m, k]; } }));
  return best;
}
svg.addEventListener("pointermove", e => { if (e.pointerType === "mouse") svg.style.cursor = nearest(svgPoint(e)) ? "pointer" : "default"; });
svg.addEventListener("click", e => {
  const hit = nearest(svgPoint(e));
  if (hit) { S.touched = true; S.selM = hit[0]; open(PR[hit[1]].key); show(); }
});
document.addEventListener("click", e => {
  const w = e.target.closest("[data-rule]"), o = e.target.closest("[data-open]"), s = e.target.closest("[data-step]");
  if (w) { S.touched = true; if (Number(w.dataset.rule) !== S.rule) { setRule(Number(w.dataset.rule)); address(false); pane(); } }
  if (o) open(o.dataset.open);
  if (s) {
    const k = PR.findIndex(p => p.key === S.open);
    open(PR[(k + Number(s.dataset.step) + N) % N].key);
    $("pane").querySelector(`[data-step="${s.dataset.step}"]`).focus({ preventScroll: true });
  }
});
document.addEventListener("keydown", e => {
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  if (e.key === "Escape" && S.open) open("");
  if ((e.key === "ArrowRight" || e.key === "ArrowLeft") && !e.target.closest("button")) {
    const r = e.key === "ArrowRight" ? 1 : 0;
    S.touched = true;
    if (r !== S.rule) { setRule(r); address(false); pane(); }
  }
  if (e.key === "Enter" && document.activeElement === svg) {  // the first problem whose Think-SFT program the first rule did not read
    e.preventDefault();
    S.touched = true; S.selM = 1;
    open(PR[PR.findIndex(p => p.s[1][0] === "u")].key);
    show();
  }
});
addEventListener("hashchange", fromHash);
addEventListener("popstate", fromHash);
narrow.addEventListener("change", () => { build(); draw(performance.now()); });
still.addEventListener("change", () => { if (still.matches) { setRule(S.rule, true); aim(0, 0); draw(performance.now()); } });
document.fonts.ready.then(() => { S.shown = {}; draw(performance.now()); });  // measure the row names again in the loaded typeface
const stage = $("stage");
stage.addEventListener("pointermove", e => {
  if (e.pointerType !== "mouse" || still.matches) return;
  const b = stage.getBoundingClientRect();
  V.tx = 2 * (e.clientX - b.left) / b.width - 1; V.ty = 2 * (e.clientY - b.top) / b.height - 1;
});
stage.addEventListener("pointerleave", () => { V.tx = V.ty = 0; });

$("problem").textContent = C.problem;
$("say").innerHTML = esc(C.line).replace(/(?<![\w-])(\d+(?:[.,]\d+)*(?: ?%)?)/g, "<b>$1</b>");
build();
aim(0, 0);
fromHash(true);
draw(performance.now());
if (!still.matches) {
  svg.classList.add("enter");
  setTimeout(() => svg.classList.remove("enter"), 2200);
}
requestAnimationFrame(frame);
</script>
<script type="application/json" id="texts">__TEXTS__</script>
</body>
</html>
"""

# The icon of this finding's tile on /findings (tools/findings.py says how it is called): the page's own picture,
# reduced. A glass slab with three rows of dots, each sorted passed (lit) then failed (faint); the middle row has three red
# dots, programs not read, which every few seconds turn into two lit dots and one faint one and back.
ICON = r"""(kit, t, tilt) => {
  const th = 5, w = th / 2, cols = 12, x0 = -31, dx = 62 / (cols - 1), read = Math.sin((Number(t) || 0) * .55) > -.2;
  const rows = [[-14, 7, 0], [0, 6, 3], [14, 9, 0]];
  let out = kit.slab(44, 38, th);
  rows.forEach(([v, lit, red]) => {
    for (let i = 0; i < cols; i++) {
      const p = kit.at(x0 + i * dx, v, w), isRed = i >= lit && i < lit + red;
      const on = i < lit || (isRed && read && i < lit + 2), col = isRed && !read ? "var(--red)" : on ? kit.token.blue : kit.token.ink;
      out += `<ellipse cx="${p[0].toFixed(2)}" cy="${p[1].toFixed(2)}" rx="${(1.9 * p[2]).toFixed(2)}" ry="${(1.35 * p[2]).toFixed(2)}" ` +
        `fill="${col}" opacity="${on || (isRed && !read) ? .92 : .22}"/>`;
    }
  });
  return out;
}"""

# The picture needs per problem only its uid and three states; the texts go in a block read on the first click ("</"
# escaped so no text ends the block).
PAGE = PAGE.replace("__TITLE__", TITLE).replace("__CONFIG__", json.dumps({
    "problem": PROBLEM, "line": LINE, "panels": PANELS,
    "problems": [[p[0]] + [c[0] for c in p[2:]] for p in PROBLEMS],
    "prefix": [DATA["code_prefix"].get(c, []) for c in CELLS],
    "data": {"n": DATA["n"], "cap": DATA["cap"],
             "diff": {r: {c: v for c, v in d.items()} for r, d in DATA["diff"].items()}}},
    ensure_ascii=False).replace("</", "<\\/")).replace("__TEXTS__", json.dumps(
    {"tasks": [p[1] for p in PROBLEMS], "rows": [[c[1:] for c in p[2:]] for p in PROBLEMS]}, ensure_ascii=False).replace("</", "<\\/"))


def _git(path):  # a file at the copied commit of branch audit; the working tree's copy when that commit is not in this clone
    got = subprocess.run(["git", "show", f"{DATA['commit']}:{path}"], capture_output=True, text=True)
    return got.stdout if got.returncode == 0 else open(path).read()


if __name__ == "__main__":  # run from the repository root (see the docstring)
    args = sys.argv[1:]
    runs = args[args.index("--runs") + 1] if "--runs" in args else "runs"
    have = os.path.exists(os.path.join(runs, DATA["rows"].format(cell=CELLS[0])))
    if "--write" in args:
        assert have, f"no rows under {runs}"
        problems, _ = _build(runs)
        src = open(__file__).read()
        start = src.index("\nPROBLEMS = [") + 1
        end = src.index("\n]\n", start) + 2
        src = src[:start] + "PROBLEMS = [\n" + "".join("    " + json.dumps(p, ensure_ascii=False) + ",\n" for p in problems) + "]" + src[end:]
        open(__file__, "w").write(src)
        sys.exit(f"wrote {len(problems)} problems")
    import numpy as np

    st = lambda c, r: [p[2 + CELLS.index(c)][0][r] for p in PROBLEMS]  # outcome letters of one row under rule r (0 or 1)
    assert len(PROBLEMS) == DATA["n"]
    r1, r2, r3 = (json.loads(_git(DATA[k])) for k in ("readout_v1", "readout_v2", "readout_v3"))
    for c in CELLS + ["base_mathcue", "sft1_mathcue"]:  # the copied counts against the three readouts
        assert DATA["passed"]["v1"][c] == r1["cells"][c]["all"]["passed"] == r3["cells"][c]["passed_v1"], c
        assert DATA["passed"]["v2"][c] == r2["cells"][c]["passed_v2"] and DATA["passed"]["v3"][c] == r3["cells"][c]["passed_v3"], c
    for c in CELLS:  # and recomputed from PROBLEMS
        rows = [p[2 + CELLS.index(c)] for p in PROBLEMS]
        assert st(c, 0).count("p") == DATA["passed"]["v1"][c] and st(c, 1).count("p") == DATA["passed"]["v3"][c], c
        ch = [x for x in rows if len(x[0]) == 3]
        assert [len(ch), sum(x[0][1] == "p" for x in ch)] == DATA["rerun"][c] == [r3["cells"][c]["rerun"], r3["cells"][c]["rerun_passed"]], c
        assert all(x[0][0] == "u" or (x[0][0] == "p" and len(x[0]) == 3) for x in ch) and all(x[0][0] != "u" for x in rows if len(x[0]) == 2), c
        assert DATA["tokens"][c] == round(r1["cells"][c]["all"]["tokens_per_problem"]) == round(sum(x[1] for x in rows) / DATA["n"]), c
        assert sum(x[2] for x in rows) == r1["cells"][c]["all"]["cap_hits"], c
    assert sum(p[3][0].endswith("o") for p in PROBLEMS) == DATA["unopened_v3"] == r3["cells"]["sft1_codecue"]["modes"]["unopened"]
    assert r3["instrument_check"]["bad"] == [] and r2["instrument_check"]["bad"] == [] and r3["instrument_check"]["n"] == DATA["n"]
    sft = lambda r, s: sum(p[3][0][r] == "p" for p in PROBLEMS if p[0].startswith(s))
    assert {s: sft(0, s) for s in DATA["sets"]} == DATA["first_by_set"] == {"HumanEval": r1["cells"]["sft1_codecue"]["humanevalplus"]["passed"],
                                                                         "Mbpp": r1["cells"]["sft1_codecue"]["mbppplus"]["passed"]}
    assert {s: sft(1, s) for s in DATA["sets"]} == _v3set and {s: sum(p[0].startswith(s) for p in PROBLEMS) for s in DATA["sets"]} == DATA["sets"]
    # the paired intervals, recomputed as analysis/code_regrade_readout.py does: problems in sorted uid order, one set of
    # 5,000 resamples of the 538 from default_rng(0), shared by every pair
    order = sorted(range(DATA["n"]), key=lambda k: PROBLEMS[k][0])
    idx = np.random.default_rng(0).integers(0, DATA["n"], (5000, DATA["n"]))
    for c in ("base_cue", "rl_plain"):
        x = r3["differences_points"][f"{c} - sft1_codecue"]
        d = np.array([float(st("sft1_codecue", 1)[k] == "p") - float(st(c, 1)[k] == "p") for k in order])
        mine = [100 * d.mean()] + np.percentile(100 * d[idx].mean(1), [2.5, 97.5]).tolist()
        assert np.allclose(mine, DATA["diff"]["v3"][c]) and DATA["diff"]["v3"][c] == [-x["points"], -x["bootstrap95"][1], -x["bootstrap95"][0]], (c, mine)
        y = r1["differences"][f"sft1_codecue - {c}"]
        assert DATA["diff"]["v1"][c] == [y["points"]] + y["bootstrap95"] and np.isclose(y["points"], 100 * (DATA["passed"]["v1"]["sft1_codecue"] - DATA["passed"]["v1"][c]) / DATA["n"])
    assert r1["cells"]["sft1_codecue"]["prefix_text"] == DATA["code_cue"] == r1["cells"]["base_cue"]["prefix_text"]
    ex = json.loads(_git(DATA["examples_v3"]))  # the committed examples against PROBLEMS
    for e in ex.values():
        p = next(p for p in PROBLEMS if p[0] == e["uid"])
        assert p[3][0][1] == ("p" if e["passed_v3"] else "f") and e["answer_end"].endswith(p[3][5]), e["uid"]
    readme = _git("studies/rlneurons/README.md")
    assert "### Regrade with two more extraction rules" in readme and "| Think-SFT + Code cue | 301 | 318 | 381 |" in readme
    assert "+10.8 [6.5, 15.2]" in readme and "-3.7 [-7.6, 0.0]" in readme and DATA["models"]["rl"] in readme
    spec = _git(DATA["spec"].split(",")[0])
    assert "only 17 of the 101 unopened programs pass, because 72 of them fail with `NameError: name 'CODE' is not defined`" in spec
    assert DATA["v2_unopened"] == [101, 17, 72]
    for s in (f"passes {DATA['passed']['v3']['sft1_codecue']} of {DATA['n']}", f"{_n1(_d3['base_cue'][0])} points above Base + cue",
              f"{_n1(-_d3['rl_plain'][0])} below RL"):
        assert s in LINE, s
    assert 18 <= len(LINE.replace(" + ", " ").split()) <= 26, len(LINE.split())
    print("DATA, LINE and PROBLEMS match", DATA["readout_v1"], DATA["readout_v2"], DATA["readout_v3"], DATA["examples_v3"],
          f"(commit {DATA['commit'][:7]} or the working tree), the README and the spec; intervals recomputed")
    if not have:
        print(f"Row comparison skipped: {os.path.join(runs, DATA['rows'].format(cell='<cell>'))} is not here (the regrade job's "
              "output, not in git); pass --runs <folder> to compare.")
    else:
        problems, rows = _build(runs)
        assert PROBLEMS == problems, "PROBLEMS differs from the rows: run with --write"
        for c in CELLS:
            m = json.load(open(os.path.join(runs, DATA["rows"].format(cell=c)).replace("answers_v3.jsonl", "metrics_v3.json")))
            assert m == r3["cells"][c], c
        code_lib = "studies/rlneurons/lib/code_lib.py"
        if os.path.exists(code_lib) and "def extract_v2" in open(code_lib).read():
            sys.path.insert(0, ".")
            from studies.rlneurons.lib import code_lib as CL
            for c in CELLS:  # extract_v3 against "without the lines that are only CODE", the rule as written
                odd = [r["uid"] for r in rows[c] if re.sub(r"(?m)^[ \t]*CODE[ \t]*(\n|$)", "", CL.extract_v2(r["text"])[1]) != CL.extract_v3(r["text"])[1]]
                assert odd == DATA["code_prefix"].get(c, []), (c, odd)
                for u in odd:  # read by its words, the rule leaves these programs as the first rule read them
                    r = next(r for r in rows[c] if r["uid"] == u)
                    assert re.sub(r"(?m)^[ \t]*CODE[ \t]*(\n|$)", "", CL.extract_v2(r["text"])[1]) == r["code"], u
            b = rows["base_cue"]
            assert DATA["base_whole_lines"] == sum(r["passed"] if r["uid"] in DATA["code_prefix"]["base_cue"] else r["passed_v3"] for r in b)
            print("extract_v3 checked against the rule as written:", DATA["code_prefix"])
        else:
            print("extract_v3 check skipped: studies/rlneurons/lib/code_lib.py of branch audit is not here")
        print("PROBLEMS matches the rows under", runs, "and the metrics_v3.json files match readout_v3")
